SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ── Solver-specific tables (CREATE IF NOT EXISTS) ──

CREATE TABLE IF NOT EXISTS `solver_locations` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(255) NOT NULL,
  `lat` DOUBLE NOT NULL,
  `lon` DOUBLE NOT NULL,
  `type` ENUM('depot', 'delivery') NOT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `solver_customers` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(255) NOT NULL,
  `address` VARCHAR(500),
  `lat` DOUBLE NOT NULL,
  `lon` DOUBLE NOT NULL,
  `phone` VARCHAR(20),
  `preferred_time_start` VARCHAR(10),
  `preferred_time_end` VARCHAR(10),
  `notes` TEXT,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `solver_vehicles` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(255) NOT NULL,
  `type` VARCHAR(50) NOT NULL,
  `max_speed_kmh` DOUBLE NOT NULL,
  `avg_city_speed_kmh` DOUBLE NOT NULL,
  `capacity_kg` DOUBLE DEFAULT 0,
  `capacity_cbm` DOUBLE DEFAULT 0,
  `fuel_type` VARCHAR(20),
  `specs_source` VARCHAR(50),
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `solver_orders` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `order_code` VARCHAR(20),
  `customer_id` BIGINT UNSIGNED,
  `status` VARCHAR(20),
  `total_quantity` INT DEFAULT 0,
  `total_weight_kg` DOUBLE DEFAULT 0,
  `total_volume_cbm` DOUBLE DEFAULT 0,
  `time_window_start` VARCHAR(10),
  `time_window_end` VARCHAR(10),
  `delivery_date_preferred` DATE,
  `notes` TEXT,
  `source` VARCHAR(50),
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NULL,
  `order_date` DATE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `solver_order_items` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `order_id` BIGINT UNSIGNED,
  `product_name` VARCHAR(255),
  `quantity` INT DEFAULT 0,
  `weight_per_unit_kg` DOUBLE DEFAULT 0,
  `volume_per_unit_cbm` DOUBLE DEFAULT 0,
  `total_weight_kg` DOUBLE DEFAULT 0,
  `total_volume_cbm` DOUBLE DEFAULT 0,
  `is_fragile` TINYINT(1) DEFAULT 0,
  `is_heavy` TINYINT(1) DEFAULT 0,
  `notes` TEXT,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `solver_traffic_events` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `event_name` VARCHAR(255) NOT NULL,
  `event_type` VARCHAR(50) NOT NULL,
  `start_date` DATE,
  `end_date` DATE,
  `traffic_impact_factor` DOUBLE DEFAULT 1.0,
  `description` TEXT,
  `source` VARCHAR(100),
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `solver_optimization_runs` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `run_id` VARCHAR(50) UNIQUE NOT NULL,
  `status` VARCHAR(20),
  `progress_pct` INT DEFAULT 0,
  `current_stage` VARCHAR(500),
  `total_orders` INT DEFAULT 0,
  `total_vehicles` INT DEFAULT 0,
  `planning_days` INT DEFAULT 1,
  `result_json` LONGTEXT,
  `error_message` TEXT,
  `started_at` TIMESTAMP NULL,
  `completed_at` TIMESTAMP NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `solver_trip_history` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `vehicle_id` INT,
  `route_json` LONGTEXT,
  `estimated_time_min` DOUBLE,
  `actual_time_min` DOUBLE,
  `departure_time` VARCHAR(20),
  `arrival_time` VARCHAR(20),
  `estimated_distance_km` DOUBLE,
  `weather_factor` DOUBLE DEFAULT 1.0,
  `target_hour` INT,
  `num_stops` INT DEFAULT 0,
  `num_traffic_lights` INT DEFAULT 0,
  `status` VARCHAR(20),
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `started_at` TIMESTAMP NULL,
  `completed_at` TIMESTAMP NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `solver_ai_corrections` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `zone_lat` DOUBLE,
  `zone_lon` DOUBLE,
  `hour_bucket` INT,
  `correction_factor` DOUBLE DEFAULT 1.0,
  `sample_count` INT DEFAULT 0,
  `last_updated` TIMESTAMP NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

